#!/usr/bin/env python3
"""Reconstruct frozen v316 without running any solver or registering evaluation.
Only line edits are encoded; existing NN weights and test answers are not duplicated.
"""
from pathlib import Path
import base64,difflib,hashlib,json,zlib
ROOT=Path(__file__).resolve().parents[2]
PARENT='0c321cd70539ddcfeab378a26502c48733224b0921a5433cc4b87ef8689d363b'
EXPECTED='b678291c41394ed0c8f6571ac79569f890f3cb8297553c50f743e56f5dd6ae2a'
PAYLOAD=''
source=ROOT/'src/bin/v314_conditional_support.cpp'
original=source.read_text()
assert hashlib.sha256(original.encode()).hexdigest()==PARENT,'parent source changed'
lines=original.splitlines(True)
for a,b,replacement in reversed(json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))):
    lines[a:b]=replacement
result=''.join(lines)
assert hashlib.sha256(result.encode()).hexdigest()==EXPECTED,'reconstruction mismatch'
destination=ROOT/'src/bin/v316_integrated_neural_lns.cpp'
if destination.exists():assert destination.read_text()==result,'existing v316 differs'
destination.write_text(result)
patch=ROOT/'adhoc/v316/v316_vs_v314.patch'
patch.parent.mkdir(parents=True,exist_ok=True)
patch.write_text(''.join(difflib.unified_diff(original.splitlines(True),result.splitlines(True),fromfile='a/src/bin/v314_conditional_support.cpp',tofile='b/src/bin/v316_integrated_neural_lns.cpp')))
print(EXPECTED,destination)
